"""
    Test if a symbol or label is defined.

    :param s: The symbol to look up.
    :param table: A dictionary containing the labels and symbols.
    :return: True if defined, False otherwise.
    """
def is_defined(s: Any, table: Any) -> object {
    try {
        table[s];
        return True;
    } except KeyError {
        return False;
    }
}

"""Return width, height, x center, and y center for an anchor (window).
  """
def genwhctrs(anchor: Any) -> object {
    base_w = (anchor[2] - anchor[0]) + 1;
    base_h = (anchor[3] - anchor[1]) + 1;
    x_ctr = anchor[0] + (0.5 * (base_w - 1));
    y_ctr = anchor[1] + (0.5 * (base_h - 1));
    return (base_w, base_h, x_ctr, y_ctr);
}

