"""Converts a 1-char byte string to int.

    This function is used for python2 and python3 compatibility
    that can also handle an integer input.

    Args:
        i: The 1-char byte string to convert to an int.

    Returns:
        The byte string value as int or i if the input was already an
        integer.

    """
def _ord(i: Any) -> object {
    if isinstance(i, int) {
        return i;
    } else {
        return ord(i);
    }
}

"""
    Creates a dict to use with send_list
    :param title: Element title
    :param subtitle: Element subtitle (optional)
    :param image_url: Element image URL (optional)
    :param buttons: List of button_postback to show under the element (optional)
    :param default_action: Action generated by button_url (optional)
    :return: dict
    """
def list_element(
    title: Any,
    subtitle: Any = None,
    image_url: Any = None,
    buttons: Any = None,
    default_action: Any = None
) -> object {
    payload = {
        "title": title,
        "image_url": image_url,
        "subtitle": subtitle,
        "default_action": default_action,
        "buttons": buttons
    };
    if not subtitle {
        payload.pop('subtitle');
    }
    if not image_url {
        payload.pop('image_url');
    }
    if not buttons {
        payload.pop('buttons');
    }
    if not default_action {
        payload.pop('default_action');
    }
    return payload;
}
